import{I as e,L as t,O as n,j as r,k as i,t as a}from"./app-DO0QAytN.js";var o=JSON.parse(`{"path":"/interview/agent-interview/react-principle.html","title":"ReAct 是什么？说说它的原理","lang":"zh-CN","frontmatter":{"title":"ReAct 是什么？说说它的原理","icon":"mdi:thought-bubble","tag":["ReAct","推理","Agent"],"description":"ReAct 是什么？说说它的原理 这道题考的是 ReAct 推理框架的核心原理，本质是&quot;大模型如何把思考和行动结合起来&quot;这个问题。面试官想看你能不能说清楚：为什么需要 ReAct？它比 CoT 好在哪？它是怎么工作的？ 我分四个部分来讲：先说 CoT 的局限性，再说 ReAct 的原理，接着说为什么它有效，最后说现代 LLM 对它的...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"ReAct 是什么？说说它的原理\\",\\"image\\":[\\"https://www.anyiai.cc/logo.png\\"],\\"dateModified\\":\\"2026-10-28T04:17:51.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"安逸Ai\\"}]}"],["meta",{"property":"og:url","content":"https://www.anyiai.cc/interview/agent-interview/react-principle.html"}],["meta",{"property":"og:site_name","content":"AI 学习资源站"}],["meta",{"property":"og:title","content":"ReAct 是什么？说说它的原理"}],["meta",{"property":"og:description","content":"ReAct 是什么？说说它的原理 这道题考的是 ReAct 推理框架的核心原理，本质是&quot;大模型如何把思考和行动结合起来&quot;这个问题。面试官想看你能不能说清楚：为什么需要 ReAct？它比 CoT 好在哪？它是怎么工作的？ 我分四个部分来讲：先说 CoT 的局限性，再说 ReAct 的原理，接着说为什么它有效，最后说现代 LLM 对它的..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://www.anyiai.cc/logo.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-10-28T04:17:51.000Z"}],["meta",{"property":"article:tag","content":"Agent"}],["meta",{"property":"article:tag","content":"推理"}],["meta",{"property":"article:tag","content":"ReAct"}],["meta",{"property":"article:modified_time","content":"2026-10-28T04:17:51.000Z"}],["link",{"rel":"canonical","href":"https://www.anyiai.cc/interview/agent-interview/react-principle.html"}]]},"git":{"createdTime":1793161071000,"updatedTime":1793161071000,"contributors":[{"name":"anyi","username":"anyi","email":"1961741003@qq.com","commits":1,"url":"https://github.com/anyi"}]},"readingTime":{"minutes":1.78,"words":535},"filePathRelative":"interview/agent-interview/react-principle.md","autoDesc":true}`),s={name:`react-principle.md`};function c(a,o,s,c,l,u){let d=t(`ReadMoreLock`);return e(),n(`div`,null,[o[0]||=i(`<h1 id="react-是什么-说说它的原理" tabindex="-1"><a class="header-anchor" href="#react-是什么-说说它的原理"><span>ReAct 是什么？说说它的原理</span></a></h1><p>这道题考的是 <strong>ReAct 推理框架的核心原理</strong>，本质是&quot;大模型如何把思考和行动结合起来&quot;这个问题。面试官想看你能不能说清楚：为什么需要 ReAct？它比 CoT 好在哪？它是怎么工作的？</p><p>我分四个部分来讲：先说 CoT 的局限性，再说 ReAct 的原理，接着说为什么它有效，最后说现代 LLM 对它的进化。</p><hr><h2 id="先有-cot-推理-才有-react-行动" tabindex="-1"><a class="header-anchor" href="#先有-cot-推理-才有-react-行动"><span>先有 CoT 推理，才有 ReAct 行动</span></a></h2><p>在说 ReAct 之前，得先说它的前身——<strong>CoT（Chain of Thought）思维链</strong>。</p><p>CoT 干的事情很简单：让大模型在回答问题的时候，把推理步骤一步一步写出来。比如问&quot;小明有5个苹果，给了小红2个，还剩几个？&quot;，CoT 会让模型输出&quot;5 - 2 = 3，所以还剩3个&quot;。</p><p>这比直接蹦答案强多了。模型能把中间过程暴露出来，推理更稳，答案更准。</p><p><strong>但 CoT 有个根本问题：它只让模型&quot;想&quot;，不让模型&quot;做&quot;。</strong></p><p>模型在脑子里推理了半天，最后还是只能给你一段文字。它没法去查天气、没法算数学、没法查数据库，所有&quot;需要动手干的事&quot;，它都干不了。</p><p>这就好比一个学霸，解题步骤写得漂漂亮亮，但最后算结果的时候，只能靠猜。</p><p>ReAct 就是来解决这个问题的——它让模型不仅能想，还得能行动。</p><hr>`,13),r(d),o[1]||=i(`<h2 id="react-的工作原理——推理链中插入行动" tabindex="-1"><a class="header-anchor" href="#react-的工作原理——推理链中插入行动"><span>ReAct 的工作原理——推理链中插入行动</span></a></h2><p><strong>ReAct = Reasoning + Acting</strong>，翻译过来就是&quot;推理 + 行动&quot;。</p><p>它的核心思想是：在模型的推理链里，插入&quot;行动&quot;这个环节。模型推理到一半，可以调用外部工具，完成后再把结果接回来继续推理。</p><p>怎么实现的？</p><p><strong>通过 prompt 格式约束。</strong></p><p>给大模型一套固定的&quot;剧本格式&quot;，让它按这个格式输出。这套格式长这样：</p><p>Thought: 我现在要做什么<br> Action: 我要调用什么工具</p>`,7)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};